import { action, observable, toJS, computed, makeObservable } from "mobx";
import { CustomPageStore } from '@/components/CustomPage';
import type { TabPaneProps } from "@arco-design/web-react/es/Tabs";
import CodeStore from '@/components/MonacoEditor/code/store';
import { Message, Modal } from "@arco-design/web-react";
import { treeToFlatten } from "@/utils";
import { moduleStore, ContextStore } from "react-converter-code";
import ajax from "@/utils/ajax";
import { dynamicCreateModule } from "@/environments/hoc";
import _ from "lodash";
import { ModuleItem } from "@/components/CustomPage/interface";
import { content } from "html2canvas/dist/types/css/property-descriptors/content";


interface TabItem extends TabPaneProps {
    key: string;
    isComponent?: boolean;
}
interface OptionProps {
    content?: any;
}
class Store {
    code = new CodeStore();

    @observable text: any = '';
    @action setText = (text) => {
        this.text = text;
    }

    // 记录当前text store
    rightStore: CustomPageStore = new CustomPageStore({});
    @action
    updatePageElement = async () => {
        // // 暂时逻辑先改成根据tab 切换
        // const pageStore = this.pageStore[this.activeTab];
        // if(pageStore){
        //     const text = await pageStore.getRenderText();
        //     this.setPageElement(dynamicCreateModule(text));
        // }
        const filePath = `file:${this.code.uri.fsPath}`;
        const page = this.pageStore[this.pathMap[filePath]];
        if (page) {
            this.rightStore = page;
            const text = await page.getRenderText();
            this.setText(text);
        } else {
            const page2 = this.pageStore[this.activeTab];
            this.rightStore = page2;
            const text2 = await page2.getRenderText();
            this.setText(text2);
        }
    }

    @observable pVisible = false;
    @action setPVisible = (bool: boolean) => {
        this.pVisible = bool;
    }

    @observable right = false;
    @action setRight = (bool: boolean) => {
        this.right = bool
    }

    // 路径映射表, 记录url 路径对应的文件uid
    pathMap = {};

    @observable activeTab = '';
    @action
    setActiveTab = (key) => {
        this.activeTab = key;
    }

    pageStore: Record<string, CustomPageStore> = {};
    contexts: Record<string, ContextStore> = {};

    @observable tabList: TabItem[] = [];
    @action
    setTabList = (list) => {
        this.tabList = list;
    }

    constructor() {
        makeObservable(this);
    }

    // 打开新的文件
    @action
    async openModuleEidt(moduleId) {
        if (this.pageStore[moduleId]) {
            this.setActiveTab(moduleId)
        } else {
            await this.addTab(moduleId);
            this.setActiveTab(moduleId);
        }
    }

    async addTabPage({ key, title, content, extraInfo }) {
        const item = {
            key,
            uid: key,
            title,
            name: title,
        }
        const pageStore = new CustomPageStore(item);
          if(extraInfo){
            if(extraInfo.components) await moduleStore.syncModuleIds(extraInfo.components)
            pageStore.previewImg = extraInfo?.previewImg;
        }
        if(content) pageStore.setData(content);
        this.pageStore[key] = pageStore;
        this.setTabList([...toJS(this.tabList), item]);
        this.setActiveTab(item.key);
    }

    @action
    async addTab(moduleId) {
        const module = moduleStore.elements.get(moduleId);
        const extraInfo = module.extraInfo;
        const item = {
            key: moduleId, // tab 中使用
            uid: moduleId,
            title: module.nickname || module.name,
            name: module.name,
            isComponent: module.source === "custom",
            isContext: module.source === "context",
        };
        // console.log('module', module)
        const pageStore = new CustomPageStore(item);
        if(extraInfo && extraInfo.components) await moduleStore.syncModuleIds(extraInfo.components)
        if (module.content) await pageStore.setData(module.content);
        this.pageStore[moduleId] = pageStore;
        this.setTabList([...toJS(this.tabList), item]);
    }

    // 当前页面创建模式，canvas 基础画布 和 code VsCode 模拟编辑器
    // const [mode, setMode] = useState<'canvas' | 'code'>('canvas');
    @observable mode: 'canvas' | 'code' = "canvas";
    @action setMode(type: 'canvas' | 'code') { this.mode = type }

    /**
     * 打开页面对应所有自定义组件
     */
    allComponents = async () => {
        const Keys = Object.keys(this.pageStore);
        for (const key of Keys) {
            const store: CustomPageStore = this.pageStore[key];
            if (store.isPage) {
                const data = store.getData();
                if (data.components) {
                    for (const key of data.components) {
                        const element = moduleStore.elements.get(key);
                        if (element.source === "custom") {
                            if (!this.pageStore[element.key]) {
                                // 这里判断是否已经加载对应组建的实例
                                await this.addTab(element.key);
                            }
                        } else if (element.source === "context") {
                            // @ts-ignore 创建context 页面
                            const store = new ContextStore(element);
                            const fileText = await store.getTextFiles();
                            let filePath = `file://root/context/${element.name}.ts`;
                            this.code.addFile(fileText, filePath);
                            this.contexts[filePath] = store;
                        }
                    }
                }
            }
        }
    }

    // 切为Code 编辑器模式
    @action
    async openCodeEditor() {
        let item;
        this.pathMap = {};
        this.mode = "code";
        await this.allComponents();
        for (const key in this.pageStore) {
            const store: CustomPageStore = this.pageStore[key];
            // 生成Text 版本Store
            const { storeText, indexText } = await store.getTextFiles();
            const elements = moduleStore.elements.get(key);
            const pathStr = store.isComponent ? `components/${elements.name}` : `pages/${store.uid}`
            this.code.contentAlias[store.uid] = store.name;
            let stylePath = `file://root/${pathStr}/style.less`;
            let storePath = `file://root/${pathStr}/store.ts`;
            let indexPath = `file://root/${pathStr}/index.tsx`;
            this.code.addFile(store.lessStr, stylePath);
            this.code.addFile(storeText, storePath);
            item = this.code.addFile(indexText, indexPath);
            if (store.uid === this.activeTab) {
                this.code.openFile(item.uri);
            }
            this.pathMap = Object.assign(this.pathMap, {
                [stylePath]: store.uid,
                [storePath]: store.uid,
                [indexPath]: store.uid,
            })
        }
    }

    @action
    openCavnasEditor() {
        const list = Object.values(this.contexts);
        const result = list.filter((o) => o.isSave);
        if (result.length) {
            const names = result.map((o) => o.item.nickname || o.item.name).join(',');
            Modal.confirm({
                title: "保存提示",
                content: `${names} 等context组件还未保存，是否继续切换`,
                onOk: () => {
                    this.setMode('canvas');
                }
            })
        } else {
            this.setMode('canvas');
        }
    }

    async saveData() {
        if (this.mode === "canvas") {
            const pageStore = this.pageStore[this.activeTab];
            return this.savePageData(pageStore)
        } else if (this.mode === "code") {
            const filePath = `file:${this.code.uri.fsPath}`;
            const store = this.contexts[filePath];
            if (store) {
                const module = store.item;
                // 更新context 类型
                return ajax.post('/apijson/put', {
                    Module: {
                        id: module.uid,
                        props: store.item.props,
                        extraInfo: store.item.extraInfo,
                    }
                }).then(() => {
                    Message.success(`${module.nickname || module.name} 模块保存成功`);
                    moduleStore.updateElement(this.activeTab, module)
                })
            } else {
                const page = this.pageStore[this.pathMap[filePath]];
                return this.savePageData(page);
            }
        }
    }

    /** 页面或组件内容保存 */
    async savePageData(pageStore: CustomPageStore) {
        console.log('savePageData', pageStore)
        if (pageStore.isComponent) {
            const module = moduleStore.elements.get(pageStore.uid);
            await pageStore.validate().then(async (data) => {
                // const keys = ['components', 'portal', 'isOriginal', 'defaultProps', 'isRef', 'refProps', 'refBody', 'useImperativeHandle', 'className']
                const resProps: Partial<ModuleItem> = {
                    props: data.page.props,
                    content: data,
                    extraInfo: {
                        // ..._.pick(module.extraInfo, keys),
                        ...module.extraInfo,
                        cssStr: data.cssStr,
                        previewImg: data.previewImg || module.extraInfo?.previewImg,
                        components: data.components,
                    },
                    jsxRender: await pageStore.getRenderText(),
                }
                delete data.cssStr;
                delete data.previewImg;
                delete data.components;
                return ajax.post('/apijson/put', {
                    Module: {
                        id: module.uid,
                        ...resProps,
                        content: JSON.stringify(data),
                    }
                }).then(() => {
                    Message.success(`${module.nickname || module.name} 模块保存成功`);
                    moduleStore.updateElement(pageStore.uid, {
                        ...module,
                        ...resProps,
                    } as any)
                    // history.goBack();
                })
            })
        } else {
            await pageStore.validate().then(async (data) => {
                const { previewImg, cssStr, components, ...content  } = data;
                return ajax.post('/apijson/put', {
                    Page: {
                        id: pageStore.uid,
                        content: JSON.stringify(content),
                        extraInfo: {
                            previewImg,
                            cssStr: data.cssStr,
                            components: data.components,
                        },
                        jsxRender: await pageStore.getRenderText(),
                    }
                }).then(() => {
                    Message.success('页面保存成功');
                    // history.goBack();
                })
            })
        }
    }


    /**
     * 更新当前页面实例数据
     */
    syncUpddatePageStore = async () => {
        // 通过path 获取到当前 页面实例
        const filePath = `file:${this.code.uri.fsPath}`;
        const store = this.contexts[filePath];
        if (store) {
            // context 特殊类型更新
            const fileStore = this.code.fileStores[this.code.uri.path];
            if (fileStore) {
                store.parseFileToData(fileStore.dataStr)
                fileStore.setOriginStr(fileStore.dataStr);
            }
            return;
        }
        const page = this.pageStore[this.pathMap[filePath]];
        const fileStore = this.code.fileStores[this.code.uri.path];
        // console.log('syncUpddatePageStore', page, this.pathMap, this.pageStore, this.code.uri)
        if (fileStore) {
            // const value = this.code.model.getValue();
            const value = fileStore.dataStr;
            fileStore.setLoading(true);
            const paths = this.code.uri.path.split('/');
            const fileName = paths.pop();
            if (fileName.endsWith(".less")) {
                page.setLess(value);
                fileStore.setOriginStr(value);
                fileStore.setLoading(false);
            } else {
                switch (fileName) {
                    case "index.tsx":
                        await page.parsePageIndexText(value)
                            .then(() => {
                                fileStore.setOriginStr(value);
                            }).catch((err) => {
                                Message.warning(err)
                            })
                        break;
                    case "store.tsx":
                    case "store.ts":
                        await page.parsePageStoreText(value).then(() => {
                            fileStore.setOriginStr(value);
                        }).catch((err) => {
                            Message.warning(err)
                        })
                        break;
                }
                fileStore.setLoading(false);
            }
        }
        if(this.right) {
            this.updatePageElement();
        }
    }
}

export default Store;